const Waveform = ({ color }: { color: string }) => {
  const frame = useCurrentFrame();
  const bars = [0, 1, 2, 3, 4, 5];
  
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 3, height: 20 }}>
      {bars.map((i) => {
        // Create organic wiggling effect
        const speed = 0.3;
        const offset = i * 2;
        const heightMultiplier = Math.sin(frame * speed + offset);
        // Map sine wave (-1 to 1) to height range (3px to 18px)
        const height = interpolate(heightMultiplier, [-1, 1], [4, 18]);
        
        return (
          <div
            key={i}
            style={{
              width: 3,
              height,
              backgroundColor: color,
              borderRadius: 2,
            }}
          />
        );
      })}
    </div>
  );
};

// --- Main Component ---
const DynamicIslandCall: React.FC<DynamicIslandCallProps> = ({
  backgroundColor = "#e5e5e5",
  transparentBackground = false,
  durationInSeconds = 10,
  callerName = "The Rock",
  callerLabel = "mobile",
  callerImage = "https://malloy.blob.core.windows.net/web/testing/rock.png",
  primaryColor = "#4ade80",
  dangerColor = "#ef4444",
}) => {
  useFontLoader(["Inter", "Roboto Mono"]);
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Scale Calculation: Ensure max width (400px) fills 50% of the screen width
  const MAX_ISLAND_WIDTH = 400;
  const scale = (width * 0.5) / MAX_ISLAND_WIDTH;

  // Animation Phasing
  const START_DELAY = 20;
  const INCOMING_DURATION = 110; // Frames spent in "incoming" state
  const ANSWER_FRAME = START_DELAY + INCOMING_DURATION; // Frame when "answer" happens

  // Calculate Spring Targets based on phase
  // Phase 0: Idle (Frame < START_DELAY)
  // Phase 1: Incoming (START_DELAY <= Frame < ANSWER_FRAME)
  // Phase 2: Active (Frame >= ANSWER_FRAME)

  // Physics Configuration
  const springConfig = {
    damping: 14,
    stiffness: 120,
    mass: 0.8,
  };

  // Main Container Springs
  
  // 1. Idle -> Incoming Spring
  const incomingProgress = spring({
    frame: frame - START_DELAY,
    fps,
    config: springConfig,
  });

  // 2. Incoming -> Active Spring
  const activeProgress = spring({
    frame: frame - ANSWER_FRAME,
    fps,
    config: { ...springConfig, stiffness: 140 }, // Snappier answer
  });

  // Compound Dimensions
  
  const currentWidth = interpolate(
    incomingProgress,
    [0, 1],
    [120, 400]
  );
  
  const finalWidth = interpolate(
    activeProgress,
    [0, 1],
    [currentWidth, 360]
  );

  const currentHeight = interpolate(
    incomingProgress,
    [0, 1],
    [35, 84]
  );

  const finalHeight = interpolate(
    activeProgress,
    [0, 1],
    [currentHeight, 54]
  );
  
  const currentRadius = interpolate(
    incomingProgress,
    [0, 1],
    [17.5, 42]
  );
  
  const finalRadius = interpolate(
    activeProgress,
    [0, 1],
    [currentRadius, 27]
  );

  // Content Opacity Logic
  const incomingContentOpacity = interpolate(
    incomingProgress,
    [0.7, 1], // Delay fade in slightly
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  ) - interpolate(activeProgress, [0, 0.3], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});

  const activeContentOpacity = interpolate(
    activeProgress,
    [0.2, 0.8],
    [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );

  // Timer Logic
  const timerSeconds = Math.max(0, Math.floor((frame - ANSWER_FRAME) / fps));
  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return `${m}:${s.toString().padStart(2, "0")}`;
  };

  const bg = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bg,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Inter, sans-serif",
      }}
    >
      {/* The Dynamic Island Pill */}
      <div
        style={{
          width: finalWidth,
          height: finalHeight,
          borderRadius: finalRadius,
          backgroundColor: "#000000",
          position: "relative",
          overflow: "hidden",
          boxShadow: "0px 10px 30px rgba(0,0,0,0.2)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${scale})`, // Applied proportionate scaling
        }}
      >
        
        {/* --- INCOMING CALL CONTENT --- */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            padding: "0 20px",
            opacity: incomingContentOpacity,
            // Ensure it doesn't block clicks/view when hidden (visually)
            pointerEvents: "none",
          }}
        >
          {/* Left: Caller Info */}
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div
              style={{
                width: 48,
                height: 48,
                borderRadius: "50%",
                backgroundColor: "#333",
                backgroundImage: `url(${callerImage})`,
                backgroundSize: "cover",
                backgroundPosition: "center",
              }}
            />
            <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
              <span
                style={{
                  color: "#9ca3af",
                  fontSize: 12,
                  fontWeight: 500,
                  lineHeight: 1,
                  opacity: 0.8,
                }}
              >
                {callerLabel}
              </span>
              <span
                style={{
                  color: "white",
                  fontSize: 16,
                  fontWeight: 600,
                  lineHeight: 1,
                  whiteSpace: "nowrap",
                }}
              >
                {callerName}
              </span>
            </div>
          </div>

          {/* Right: Actions */}
          <div style={{ display: "flex", gap: 12 }}>
            {/* Decline Button */}
            <div
              style={{
                width: 48,
                height: 48,
                borderRadius: "50%",
                backgroundColor: dangerColor,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <PhoneHangupIcon size={24} />
            </div>
            {/* Accept Button */}
            <div
              style={{
                width: 48,
                height: 48,
                borderRadius: "50%",
                backgroundColor: primaryColor,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <PhoneIcon size={24} />
            </div>
          </div>
        </div>

        {/* --- ACTIVE CALL CONTENT --- */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            padding: "0 24px", // slightly more padding for cleaner look
            opacity: activeContentOpacity,
          }}
        >
          {/* Left: Timer + Icon */}
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <PhoneIcon size={16} color={primaryColor} />
            <span
              style={{
                color: primaryColor,
                fontFamily: "'Roboto Mono', monospace",
                fontSize: 18,
                fontWeight: 600,
                letterSpacing: -0.5,
                fontVariantNumeric: "tabular-nums",
                minWidth: 60,
                lineHeight: 1,
              }}
            >
              {formatTime(timerSeconds)}
            </span>
          </div>

          {/* Right: Waveform */}
          <Waveform color={interpolateColors(frame % 60, [0, 30, 60], ["#fbbf24", "#f87171", "#fbbf24"])} /> 
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default DynamicIslandCall;